// GENERATED by tools/port_rules.py from the HTML character sheet (pustelnyky-caravan/src/caravan.src.html).
// Do not edit by hand: change the HTML sheet's data and re-run the script.
import {
  IMPS,
  MEETING,
  LAST_JOB,
  WENT_WRONG,
  COMPANY,
  ASPECTS,
  DEFAULT_REP,
  REPUTATIONS,
  LOCK_KEYS,
  DEFAULT_ARMOR_TYPE,
  QUICK_START,
} from "./caravan.mjs";

/**
 * The caravan sheet's rules for one caravan state (S, the HTML sheet's .json).
 * @param {object} env  { S, toast(msg, undo) } — S may be replaced (random caravan): read it with getS()
 */
export function createCaravanLogic(env = {}) {
  let S = env.S;
  const toast = env.toast || (() => {});
  const clone = (o) => JSON.parse(JSON.stringify(o));
  const d = (n) => Math.floor(Math.random() * n) + 1;
  const pick = (arr) => arr[Math.floor(Math.random() * arr.length)];
  const int = (v, def = 0) => { const n = parseInt(v, 10); return Number.isFinite(n) ? n : def; };
  const signed = (n) => (n > 0 ? "+" + n : n < 0 ? "−" + Math.abs(n) : "0");
  const esc = (s) => String(s == null ? "" : s).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));

  function blankImps() { const o = {}; IMPS.forEach(i => o[i.id] = 0); return o; }

  function blankManual() { const o = {}; LOCK_KEYS.forEach(k => o[k] = false); return o; }

  function blankState() {
    return {
      v: 1, companyName: "", luck: 0, karma: 0, karmaAspect: "Прості волоцюги", reputation: DEFAULT_REP,
      budget: 0, tachka: false, hpCurrent: 25, moveCurrent: 10, supplies: 0,
      imp: blankImps(),
      cargo: [], counters: [],
      story: { meeting: "", face: "", lastJob: "", wentWrong: "" }, notes: "",
      longHaul: false, hpMaxOverride: null, armorOverride: null, armorType: DEFAULT_ARMOR_TYPE, customImps: [],
      manual: blankManual()
    };
  }

  function derived(st = S) {
    const t = st.tachka;
    const baseMaxHP = (t ? 35 : 25) + 10 * st.imp.structure;
    const maxHP = st.hpMaxOverride != null ? st.hpMaxOverride : baseMaxHP;
    const baseArmor = (t ? 2 : 1) + 2 * st.imp.armor;
    const armor = st.armorOverride != null ? st.armorOverride : baseArmor;
    const maxMove = 10 + 5 * st.imp.feed;
    const supCap = 3 * st.imp.chest;
    const cargoCap = 10 * (1 + st.imp.trunk);
    const customCount = st.customImps.filter(c => (c.name || "").trim() || (c.desc || "").trim()).length;
    const impCount = Object.values(st.imp).reduce((a, b) => a + b, 0) + customCount;
    let cargoVal = 0, passengers = 0;
    st.cargo.forEach(r => {
      const v = int(r.price) * Math.max(0, int(r.qty, 1));
      if (r.kind === "pass") passengers += Math.max(0, int(r.qty, 1)); else cargoVal += v;
    });
    return { maxHP, baseMaxHP, armor, baseArmor, maxMove, supCap, cargoCap, impCount, cargoVal, passengers, cells: t ? 3 : 1 };
  }

  function aspectFor(k) {
    if (k <= -20) return "Втілення зла";
    if (k <= -10) return "Запеклі негідники";
    if (k <= -5) return "Темні особи";
    if (k < 5) return "Прості волоцюги";
    if (k < 10) return "Гідні люди";
    if (k < 20) return "Поборники добра";
    return "Чемпіони Пустки";
  }

  function impName(i, st = S) { return st.tachka && i.alt ? i.alt : i.name; }

  function impSub(i, st = S) {
    if (!i.alt) return "";
    return st.tachka ? i.name + ", якщо у вас браміни" : i.alt + ", якщо у вас тачка";
  }

  function clampAfter(prevD) {
    const nd = derived();
    if (prevD && S.hpCurrent >= prevD.maxHP) S.hpCurrent = nd.maxHP;
    if (prevD && S.moveCurrent >= prevD.maxMove) S.moveCurrent = nd.maxMove;
    S.hpCurrent = Math.max(0, Math.min(S.hpCurrent, nd.maxHP));
    S.moveCurrent = Math.max(0, Math.min(S.moveCurrent, nd.maxMove));
    S.supplies = Math.max(0, Math.min(S.supplies, nd.supCap));
    if (!S.imp.bed) S.imp.defib = 0;
  }

  function normalize(o) {
    const b = blankState();
    if (!o || typeof o !== "object") return b;
    const st = Object.assign(b, o);
    st.imp = Object.assign(blankImps(), o.imp || {});
    IMPS.forEach(i => { st.imp[i.id] = Math.max(0, Math.min(i.max, int(st.imp[i.id]))); });
    st.story = Object.assign(blankState().story, o.story || {});
    st.cargo = Array.isArray(o.cargo) ? o.cargo.map(r => ({ name: String(r.name || ""), kind: r.kind === "pass" ? "pass" : "cargo", price: String(r.price ?? ""), qty: String(r.qty ?? ""), note: String(r.note || ""), ...(r.far ? { far: true } : {}), ...(r.hurt ? { hurt: true } : {}) })) : [];
    st.counters = Array.isArray(o.counters) ? o.counters.map(c => ({ name: String(c.name || ""), size: [4, 6, 8, 10, 12].includes(int(c.size)) ? int(c.size) : 6, value: Math.max(0, int(c.value)) })) : [];
    ["luck", "karma", "budget", "hpCurrent", "moveCurrent", "supplies"].forEach(k => st[k] = int(st[k]));
    st.luck = Math.max(-2, Math.min(2, st.luck));
    st.tachka = !!st.tachka;
    st.longHaul = !!o.longHaul;
    const ov = parseInt(o.hpMaxOverride, 10);
    st.hpMaxOverride = Number.isFinite(ov) && ov >= 1 ? ov : null;
    const ar = parseInt(o.armorOverride, 10);
    st.armorOverride = Number.isFinite(ar) && ar >= 0 ? ar : null;
    st.armorType = typeof o.armorType === "string" ? o.armorType : DEFAULT_ARMOR_TYPE;
    st.customImps = Array.isArray(o.customImps) ? o.customImps.map(c => ({ name: String((c && c.name) || ""), desc: String((c && c.desc) || "") })) : [];
    st.manual = blankManual();
    if (o.manual && typeof o.manual === "object") LOCK_KEYS.forEach(k => st.manual[k] = !!o.manual[k]);
    return st;
  }

  function salePrices(D, st = S) {
    const v = Math.max(0, D.cargoVal);
    return st.longHaul
      ? { sale: Math.ceil(v * 2), saleHurt: Math.ceil(v * 1.5) }
      : { sale: Math.ceil(v * 1.5), saleHurt: Math.ceil(v * 1.25) };
  }

  function isLocked(key) {
    if (!S.manual[key]) return false;
    toast(key === "imps"
      ? "Покращення обрано вручну, тож кидок заблоковано. Зніміть усі позначки покращень, щоб знову кидати."
      : "Це поле заповнили вручну, тож кістки заблоковано. Очистіть поле, щоб знову кидати.");
    return true;
  }

  function rollKarma() {
    const r = d(6);
    let v, a;
    if (r === 1) { v = -5; a = "Темні особи"; } else if (r <= 4) { v = 0; a = "Прості волоцюги"; } else { v = 5; a = "Гідні люди"; }
    S.karma = v; S.karmaAspect = a;
    return r;
  }

  function rollTwoImps() {
    const pool = IMPS.filter(i => i.id !== "defib").map(i => i.id);
    for (let k = pool.length - 1; k > 0; k--) { const j = Math.floor(Math.random() * (k + 1)); [pool[k], pool[j]] = [pool[j], pool[k]]; }
    S.imp = blankImps();
    pool.slice(0, 2).forEach(id => S.imp[id] = 1);
    S.manual.imps = false;
    return pool.slice(0, 2).map(id => impName(IMPS.find(i => i.id === id)));
  }

  function rollStory(kind) {
    const map = { meeting: [MEETING, "storyMeeting"], lastJob: [LAST_JOB, "storyLastJob"], wentWrong: [WENT_WRONG, "storyWentWrong"] };
    const [list, id] = map[kind];
    let v; do { v = pick(list); } while (list.length > 1 && v === S.story[kind]);
    S.story[kind] = v;
  }

  function rollFate() {
    const r = d(10), total = r + S.luck;
        toast(`Кістка Долі: 1d10 = ${r}, Удача партії ${signed(S.luck)} → ${total}. ${total >= 6 ? "На користь персонажів." : "Не на їхню користь."}`);
  }

  function generateRandom() {
    const prev = clone(S);
    const old = S, M = old.manual;
    S = blankState();
    S.tachka = old.tachka; S.luck = old.luck;
    S.customImps = clone(old.customImps);
    // Поля, заповнені гравцями вручну, не перекидаємо
    LOCK_KEYS.forEach(k => S.manual[k] = M[k]);
    const bits = [];
    let names = null;
    if (M.imps) S.imp = clone(old.imp); else names = rollTwoImps();
    S.manual.imps = M.imps;
    if (M.budget) S.budget = old.budget; else { const b = d(6); S.budget = b + 4; bits.push(`бюджет ${b}+4 = ${S.budget}`); }
    if (M.karma) { S.karma = old.karma; S.karmaAspect = old.karmaAspect; } else bits.push(`карма d6 = ${rollKarma()}`);
    S.companyName = M.name ? old.companyName : pick(COMPANY);
    S.story.meeting = M.meeting ? old.story.meeting : pick(MEETING);
    S.story.lastJob = M.lastJob ? old.story.lastJob : pick(LAST_JOB);
    S.story.wentWrong = M.wentWrong ? old.story.wentWrong : pick(WENT_WRONG);
    S.reputation = M.rep ? old.reputation : pick(REPUTATIONS);
    const D = derived(); S.hpCurrent = D.maxHP; S.moveCurrent = D.maxMove;
    if (names) bits.push(`покращення — ${names.join(" і ")}`);
    const kept = LOCK_KEYS.some(k => M[k]) ? ". Поля, заповнені вручну, збережено" : "";
    toast(bits.length ? `«${S.companyName}»: ${bits.join(", ")}${kept}` : `«${S.companyName}»: усе, що можна кинути, заповнено вручну. Перекинуто лише стан каравану`, prev);
  }

  function historyParts(D) {
    const parts = [];
    const qa = (q, a) => { if ((a || "").trim()) parts.push(q + " " + a.trim()); };
    qa("Як ви познайомилися?", S.story.meeting);
    qa("Хто з вас — обличчя компанії?", S.story.face);
    qa("Яку останню справу ви провернули разом?", S.story.lastJob);
    qa("Що пішло не так в останній справі?", S.story.wentWrong);
    const facts = [S.tachka ? "Тачка: 3 клітини за день і одиницю запасу ходу" : "Браміни: 1 клітина за день і одиницю запасу ходу"];
    if (S.armorType.trim() && S.armorType.trim() !== DEFAULT_ARMOR_TYPE) facts.push("Тип броні: " + S.armorType.trim());
    if (D.supCap) facts.push("Припаси: " + S.supplies + " / " + D.supCap);
    facts.push("Вантаж: " + D.cargoVal + " / " + D.cargoCap + " кришок");
    if (S.longHaul) { const sp = salePrices(D); facts.push("Далека доставка (понад 15 клітин): продаж " + sp.sale + ", пошкоджений " + sp.saleHurt + " кришок"); }
    parts.push(facts.join(". ") + ".");
    const customs = S.customImps.filter(c => (c.name || "").trim() || (c.desc || "").trim());
    if (customs.length) parts.push("Власні покращення:\n" + customs.map(c => "• " + (c.name.trim() || "Без назви") + (c.desc.trim() ? " — " + c.desc.trim() : "")).join("\n"));
    if (S.notes.trim()) parts.push(S.notes.trim());
    return parts;
  }

  return {
    getS: () => S,
    setS: (v) => { S = v; },
    blankImps,
    blankManual,
    blankState,
    derived,
    aspectFor,
    impName,
    impSub,
    clampAfter,
    normalize,
    salePrices,
    isLocked,
    rollKarma,
    rollTwoImps,
    rollStory,
    rollFate,
    generateRandom,
    historyParts,
  };
}
